package install

import (
	"context"
	"time"
)

// Logins are the passwords of the login users of the per-process roles (ADR-18), generated by Apply.
type Logins struct {
	Migrator string
	API      string
	Worker   string
}

// Login user names, members of the NOLOGIN roles of migration 0001.
const (
	MigratorLogin = "easycode_migrator"
	APILogin      = "easycode_api_login"
	WorkerLogin   = "easycode_worker_login"
)

// DatabaseProbe is what the database check found (only reads).
type DatabaseProbe struct {
	ServerVersion string `json:"server_version"`
	// CanCreate means the credential may create the database and the roles.
	CanCreate bool `json:"can_create"`
	// Exists means the database already exists; HasPlatformTables means it already has the schema.
	Exists            bool `json:"exists"`
	HasPlatformTables bool `json:"has_platform_tables"`
	// OtherPlatformDatabase is another database of the server already owned by the platform migrator.
	// The login roles belong to the server, so a second installation would rewrite their passwords.
	OtherPlatformDatabase string `json:"other_platform_database,omitempty"`
}

// DatabaseAdmin creates and migrates the database with the administrator credential.
type DatabaseAdmin interface {
	Probe(ctx context.Context, database Database) (DatabaseProbe, error)
	// Prepare creates the roles, the login users and the database owned by the migrator (idempotent).
	Prepare(ctx context.Context, database Database, logins Logins) error
	// Migrate applies the embedded migrations as the migrator and returns the schema version.
	Migrate(ctx context.Context, database Database, logins Logins) (int, error)
	// URL is the connection URL of a login user, as the processes use it.
	URL(database Database, user, password string) string
}

// Registration is what the platform records about the installation.
type Registration struct {
	Organization  Organization
	Issuer        string
	Administrator DirectoryUser
	User          *DirectoryUser
}

// SkillResult is the outcome of one organization skill package.
type SkillResult struct {
	FileName string `json:"file_name"`
	Name     string `json:"name,omitempty"`
	// Status is received (the worker scans it when the platform starts) or refused.
	Status string `json:"status"`
	Reason string `json:"reason,omitempty"`
}

// Skill results.
const (
	SkillReceived = "received"
	SkillRefused  = "refused"
)

// Installation is the lock row and file.
type Installation struct {
	InstalledAt      time.Time `json:"installed_at"`
	Mode             string    `json:"sso_mode"`
	Realm            string    `json:"realm"`
	AdministratorSub string    `json:"administrator_sub"`
	Version          string    `json:"installer_version"`
}

// Platform writes into the migrated database.
type Platform interface {
	// Register records the organization, the people and the audit record platform.install (idempotent).
	Register(ctx context.Context, registration Registration) error
	ImportSkills(ctx context.Context, registration Registration, packages []SkillPackage) ([]SkillResult, error)
	Lock(ctx context.Context, installation Installation) error
	Close()
}

// PlatformOpener connects to the migrated database (as the migrator).
type PlatformOpener func(ctx context.Context, database Database, logins Logins) (Platform, error)

// DirectoryUser is a person of the realm, without credentials.
type DirectoryUser struct {
	ID       string `json:"id"`
	Username string `json:"username"`
	Email    string `json:"email"`
	Name     string `json:"name"`
	Enabled  bool   `json:"enabled"`
}

// SSOProbe is what the SSO check found (only reads).
type SSOProbe struct {
	RealmExists bool `json:"realm_exists"`
	// Actions are the codes of what Apply creates in the realm (ESP-31 etapa 8).
	Actions []string `json:"actions"`
	// Administrators already holding the role in an existing realm (ER-31-5: a warning).
	Administrators []DirectoryUser `json:"administrators"`
}

// Integration is the generated secrets of the confidential clients.
type Integration struct {
	APISecret    string
	EventsSecret string
}

// Directory talks to the Keycloak admin API with the credential of the SSO step.
type Directory interface {
	// Probe logs in and checks the realm; conflicts come back as Invalids (ER-31-4).
	Probe(ctx context.Context, sso SSO, organization Organization) (SSOProbe, error)
	Search(ctx context.Context, sso SSO, query string) ([]DirectoryUser, error)
	// CheckPerson refuses a taken username or e-mail (new user) or a missing or disabled user (existing).
	CheckPerson(ctx context.Context, sso SSO, person Person, field string) error
	// Configure creates the realm or the missing parts of an existing one and returns the client
	// secrets in use (an unchanged existing client keeps its secret).
	Configure(ctx context.Context, sso SSO, organization Organization, integration Integration) (Integration, error)
	// EnsurePerson creates the person (or reuses the one created by an earlier try) and gives the
	// administrator role when administrator is true.
	EnsurePerson(ctx context.Context, sso SSO, person Person, administrator bool) (DirectoryUser, error)
}

// Settings are the files of the configuration directory: values without secrets, one file per secret.
type Settings struct {
	Values  map[string]string
	Secrets map[string]string
}

// ConfigStore is the configuration volume (ADR-22).
type ConfigStore interface {
	Installed() (bool, error)
	Write(settings Settings) error
	Lock(installation Installation) error
}

// SkillCatalog checks packages before the platform exists.
type SkillCatalog interface {
	// Native lists the native catalog embedded in the binaries.
	Native() ([]SkillSummary, error)
	// Check parses a package as the import does (US-44 CA-2, CA-3) and refuses a native name.
	Check(pkg SkillPackage) (SkillSummary, error)
}

// SkillSummary names a skill.
type SkillSummary struct {
	Name        string `json:"name"`
	Description string `json:"description"`
}
